from pathlib import Path

path = Path("scripts/dev/apply_memory_consumer_domain_migration.py")
text = path.read_text(encoding="utf-8")
marker = 'path = "src/ai_karen_engine/agents/agent_orchestrator.py"\n'
start = text.find(marker)
if start < 0:
    raise SystemExit("agent orchestrator transformer marker not found")
replacement = '''path = "src/ai_karen_engine/agents/agent_orchestrator.py"\ntext = read(path)\nold = ''' + '"""' + '''                    from ai_karen_engine.core.memory.unified_memory_service import (\n                        UnifiedMemoryService,\n                    )\n                    from ai_karen_engine.core.model_runtime.embedding_manager import EmbeddingManager\n                    from ai_karen_engine.database.client import (\n                        MultiTenantPostgresClient,\n                    )\n\n                    # These would normally be injected via dependency injection\n                    # For now, we'll create placeholder instances\n                    db_client = None  # Would be injected\n                    embedding_manager = None  # Would be injected\n\n                    if all([db_client, embedding_manager]):\n                        service = UnifiedMemoryService(\n                            db_client=db_client,\n                            embedding_manager=embedding_manager,\n                        )\n                        logger.info("UnifiedMemoryService discovered and initialized")\n                    else:\n                        logger.warning(\n                            "UnifiedMemoryService dependencies not available"\n                        )\n                        return None\n''' + '"""' + '''\nnew = ''' + '"""' + '''                    from ai_karen_engine.core.memory.service_factory import (\n                        create_unified_memory_service,\n                    )\n\n                    service = create_unified_memory_service()\n                    logger.info("UnifiedMemoryService discovered and initialized")\n''' + '"""' + '''\nif old not in text:\n    raise SystemExit("agent orchestrator unified construction seam not found")\ntext = text.replace(old, new, 1)\nwrite(path, text)\n'''
path.write_text(text[:start] + replacement, encoding="utf-8")
